/* Concours Maroc (Android app) — single-page router.
 *
 * Every page of the website is a route of this shell: #/concours/ensa/,
 * #/ar/guides/…, #/outils/calcul-note-bac/?bac=PC… Pages are HTML fragments
 * generated by scripts/build-app.mjs into pages/, described in
 * data/pages.json (title, language, scripts to run, practice flag…).
 *
 * Navigation pushes real history entries ({cm: depth}), shared with the
 * trainer's own screens (#/entrainement/setup…), so the Android back button
 * walks back through everything the user opened. Cordova is loaded once:
 * native plugins (speech, ads) keep their state across pages.
 */
(function (global) {
  'use strict';

  var doc = document.documentElement;
  var view = document.getElementById('view');
  var loadingBar = document.getElementById('app-loading');
  var registry = null;
  var current = null;          // { key, query, anchor, entry }
  var lastHash = null;
  var token = 0;
  var scrollMemo = {};
  var inits = {};
  var fromHistory = false;

  var PRACTICE = /^((?:ar\/)?entrainement\/)/;

  function depth() { return (history.state && history.state.cm) || 0; }

  /* '#/concours/ensa/?a=1#seuils' -> key 'concours/ensa/', query '?a=1', anchor 'seuils' */
  function parse(hash) {
    var h = String(hash || '').replace(/^#\/?/, '');
    var anchor = '';
    var i = h.indexOf('#');
    if (i !== -1) { anchor = h.slice(i + 1); h = h.slice(0, i); }
    var query = '';
    var j = h.indexOf('?');
    if (j !== -1) { query = h.slice(j); h = h.slice(0, j); }
    var m = h.match(PRACTICE);
    var key = m ? m[1] : h;
    if (key && key.charAt(key.length - 1) !== '/') key += '/';
    try { key = decodeURIComponent(key); } catch (e) { /* keep raw */ }
    return { key: key, query: query, anchor: anchor };
  }

  function langOf(key) { return key.indexOf('ar/') === 0 ? 'ar' : 'fr'; }
  function homeKey(lang) { return lang === 'ar' ? 'ar/' : ''; }
  function isHome(key) { return key === '' || key === 'ar/'; }

  /* Menu and search close as soon as a navigation starts, not when the new
     page has finished loading. */
  function closeMenus() {
    var nav = document.getElementById('site-nav');
    var menu = document.getElementById('menu-btn');
    var panel = document.getElementById('search-panel');
    var sbtn = document.getElementById('search-btn');
    if (nav) nav.classList.remove('open');
    if (menu) menu.setAttribute('aria-expanded', 'false');
    if (panel) panel.classList.remove('open');
    if (sbtn) sbtn.setAttribute('aria-expanded', 'false');
  }

  function setLoading(on) {
    if (loadingBar) loadingBar.classList.toggle('on', !!on);
  }

  // ------------------------------------------------------------ chrome
  function applyLanguage(lang) {
    if (doc.getAttribute('data-lang') === lang) return;
    doc.setAttribute('lang', lang);
    doc.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');
    doc.setAttribute('data-lang', lang);
    Array.prototype.forEach.call(document.querySelectorAll('[data-fr][data-ar]'), function (el) {
      var txt = el.getAttribute('data-' + lang);
      if (el.hasAttribute('data-label-attr')) el.setAttribute(el.getAttribute('data-label-attr'), txt);
      else el.textContent = txt;
    });
    try { localStorage.setItem('cm.lang', lang); } catch (e) { /* ignore */ }
  }

  function updateChrome(key, entry) {
    var lang = entry.l;
    // Navigation links carry a site-relative key and get the page language.
    Array.prototype.forEach.call(document.querySelectorAll('[data-key]'), function (a) {
      var k = a.getAttribute('data-key');
      var target = (lang === 'ar' ? 'ar/' : '') + k;
      a.setAttribute('href', '#/' + target);
      var section = a.getAttribute('data-section');
      var on = section ? section === entry.n : target === key;
      if (on) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');
    });
    var sw = document.getElementById('app-lang');
    if (sw) {
      var alt = entry.a !== null && entry.a !== undefined ? entry.a : homeKey(lang === 'ar' ? 'fr' : 'ar');
      sw.setAttribute('href', '#/' + alt);
      sw.setAttribute('hreflang', lang === 'ar' ? 'fr' : 'ar');
    }
    var back = document.getElementById('app-back');
    if (back) back.hidden = isHome(key);
    closeMenus();
    document.title = entry.t;
  }

  // ------------------------------------------------------------ scripts
  function runScripts(list) {
    Array.prototype.forEach.call(document.querySelectorAll('script[data-page-script]'), function (s) { s.remove(); });
    return (list || []).reduce(function (p, src) {
      return p.then(function () {
        return new Promise(function (resolve) {
          var s = document.createElement('script');
          s.src = src;
          s.async = false;
          s.setAttribute('data-page-script', '');
          s.onload = resolve;
          s.onerror = function () { console.warn('[router] script failed:', src); resolve(); };
          document.body.appendChild(s);
        });
      });
    }, Promise.resolve());
  }

  function scrollAfter(route) {
    if (route.anchor) {
      var target = document.getElementById(route.anchor);
      if (target) { target.scrollIntoView(); return; }
    }
    if (fromHistory && scrollMemo[route.key] !== undefined) global.scrollTo(0, scrollMemo[route.key]);
    else global.scrollTo(0, 0);
  }

  function notFound(route) {
    var lang = langOf(route.key);
    view.innerHTML = '';
    var box = document.createElement('div');
    box.className = 'container app-boot';
    var p = document.createElement('p');
    p.textContent = lang === 'ar' ? 'هذه الصفحة غير موجودة.' : 'Cette page n’existe pas.';
    var a = document.createElement('a');
    a.className = 'btn';
    a.href = '#/' + homeKey(lang);
    a.textContent = lang === 'ar' ? 'العودة إلى الرئيسية' : 'Retour à l’accueil';
    box.appendChild(p);
    box.appendChild(a);
    view.appendChild(box);
  }

  function emit(name, detail) {
    try { document.dispatchEvent(new CustomEvent(name, { detail: detail })); } catch (e) { /* old WebView */ }
  }

  // ------------------------------------------------------------ routing
  function route() {
    if (!registry) return Promise.resolve();
    var hash = location.hash || '#/';
    if (hash === lastHash) return Promise.resolve();
    lastHash = hash;
    closeMenus();
    var r = parse(hash);
    var entry = registry.pages[r.key];
    var practice = global.CM && global.CM.app;

    // Same page: trainer sub-route, new parameters, or an anchor.
    if (current && entry && current.key === r.key) {
      var sameQuery = current.query === r.query;
      current.anchor = r.anchor;
      if (entry.p && practice) {
        // Back/forward inside the trainer is handled by its own listeners;
        // a link (pushState, no event) must be passed on explicitly.
        if (!sameQuery && /concours=/.test(r.query)) { practice.unmount(); practice.mount(view.querySelector('#cm-app')); }
        else if (!fromHistory && practice.refresh) practice.refresh();
        current.query = r.query;
        return Promise.resolve();
      }
      if (sameQuery) { scrollAfter(r); return Promise.resolve(); }
    }

    // Leaving a page.
    if (current) {
      scrollMemo[current.key] = global.pageYOffset;
      if (current.entry && current.entry.p && practice) practice.unmount();
    }

    if (!entry) {
      current = { key: r.key, query: r.query, anchor: r.anchor, entry: null };
      applyLanguage(langOf(r.key));
      notFound(r);
      emit('cm:page', { key: r.key, lang: langOf(r.key), banner: true });
      return Promise.resolve();
    }

    var my = ++token;
    var slow = setTimeout(function () { setLoading(true); }, 120);
    return global.CM.load.text(entry.f).then(function (htmlText) {
      if (my !== token) return;
      clearTimeout(slow);
      setLoading(false);
      current = { key: r.key, query: r.query, anchor: r.anchor, entry: entry };
      applyLanguage(entry.l);
      updateChrome(r.key, entry);
      view.innerHTML = htmlText;   // generated by the build, never user input
      if (global.CMSite) global.CMSite.bindContent(view);
      return runScripts(entry.s).then(function () {
        if (my !== token) return;
        if (entry.p && practice) practice.mount(view.querySelector('#cm-app'));
        if (entry.i && inits[entry.i]) {
          try { inits[entry.i](view, entry); } catch (e) { console.error('[router] init ' + entry.i, e); }
        }
        scrollAfter(r);
        emit('cm:page', { key: r.key, lang: entry.l, banner: entry.b !== 0, practice: !!entry.p });
      });
    }).catch(function (err) {
      clearTimeout(slow);
      setLoading(false);
      console.error('[router] page failed:', r.key, err);
      if (my !== token) return;
      if (!current) throw err;   // first page: let the boot screen explain
      if (global.cmToast) global.cmToast(langOf(r.key) === 'ar' ? 'تعذر فتح الصفحة.' : 'Impossible d’ouvrir la page.');
    });
  }

  function onHistory() {
    fromHistory = true;
    route().then(function () { fromHistory = false; }, function () { fromHistory = false; });
  }
  global.addEventListener('popstate', onHistory);
  global.addEventListener('hashchange', onHistory);

  // ------------------------------------------------------------ links
  function isExternal(href) { return /^(https?:|mailto:|tel:|geo:|market:|whatsapp:)/i.test(href); }

  document.addEventListener('click', function (e) {
    if (e.defaultPrevented || e.button > 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    var a = e.target.closest ? e.target.closest('a[href]') : null;
    if (!a) return;
    var href = a.getAttribute('href');
    if (!href) return;
    if (isExternal(href)) {
      e.preventDefault();
      Router.openExternal(a.href || href);
      return;
    }
    if (href.charAt(0) !== '#') return;
    e.preventDefault();
    if (href.indexOf('#/') !== 0) {
      // In-page anchor (table of contents…): scroll without touching the route.
      var target = document.getElementById(decodeURIComponent(href.slice(1)));
      if (target) target.scrollIntoView({ behavior: 'smooth' });
      return;
    }
    Router.go(href.slice(2));
  });

  // ------------------------------------------------------------ API
  var Router = {
    /* Loads the page registry and shows the first page. */
    start: function () {
      return global.CM.load.json('data/pages.json').then(function (reg) {
        registry = reg;
        var r = parse(location.hash);
        if (!location.hash || location.hash === '#' || !registry.pages[r.key]) {
          var saved = null;
          try { saved = localStorage.getItem('cm.lang'); } catch (e) { saved = null; }
          var lang = saved || ((navigator.language || '').toLowerCase().indexOf('ar') === 0 ? 'ar' : 'fr');
          history.replaceState({ cm: 0 }, '', location.pathname + location.search + '#/' + homeKey(lang));
        } else if (!history.state) {
          history.replaceState({ cm: 0 }, '', location.href);
        }
        lastHash = null;
        return route();
      });
    },

    go: function (target, replace) {
      var hash = '#/' + String(target || '').replace(/^#?\/?/, '');
      if (hash !== location.hash || replace) {
        if (replace) history.replaceState({ cm: depth() }, '', location.pathname + location.search + hash);
        else history.pushState({ cm: depth() + 1 }, '', location.pathname + location.search + hash);
      }
      // The trainer moves the URL on its own (pushState): never trust the
      // last hash seen here when a navigation is explicitly requested.
      lastHash = null;
      fromHistory = false;
      return route();
    },

    /* Back arrow and Android back button. Returns false when there is
       nothing left to go back to (the shell then offers to exit). */
    back: function () {
      if (depth() > 0) { history.back(); return true; }
      if (current && !isHome(current.key)) { Router.go(homeKey(langOf(current.key)), true); return true; }
      return false;
    },

    current: function () { return current; },
    depth: depth,
    isHome: function () { return !current || isHome(current.key); },
    homeKey: homeKey,
    lang: function () { return doc.getAttribute('data-lang') || 'fr'; },
    onInit: function (name, fn) { inits[name] = fn; },

    /* Opens a link outside the app: the system browser, the mail app… */
    openExternal: function (url) {
      try {
        if (global.cordova && global.cordova.InAppBrowser) { global.cordova.InAppBrowser.open(url, '_system'); return; }
        if (navigator.app && typeof navigator.app.loadUrl === 'function') { navigator.app.loadUrl(url, { openExternal: true }); return; }
      } catch (e) { /* fall through */ }
      global.open(url, '_system');
    }
  };

  global.CM = global.CM || {};
  global.CM.shell = Router;
})(window);
